SPELL_ABILITY.RESOLUTION_TIME_ACTION:
local targetDC = EffectDC():Get_Targets(0) if targetDC ~= nil then local numbTargets = targetDC:Count()
for i = 0, (numbTargets-1) do local currentTarget = targetDC:Get_CardPtr(i)
if currentTarget ~= nil then
if currentTarget:CountAttachedAuras() ~= 0 then local filter = ClearFilter() filter:Add(FE_SUBTYPE, OP_IS, ENCHANTMENT_TYPE_AURA) filter:Add( FE_PARENT_CARD, OP_IS, currentTarget)
local numAuras = filter:EvaluateObjects()
for j = 0, (numAuras-1) do local aura = filter:GetNthEvaluatedObject(j)
if aura ~= nil then aura:Exile() end end end currentTarget:Exile() end end end
